struct VehicleSmokeLook {
  int effect;             // 1 = a particle-library effect sets this look
  float r, g, b, alpha;   // vertex colour, peak alpha (128 = 1)
  float size0, size1;     // half-size at birth and at death
  float life, rise;       // multipliers on the slip-driven life / rise
  int additive;           // GS additive blend, the fade in the colour
  int frames; float fps;  // flipbook (1 = a still texture)
  const char* mtl[8];     // texture frames (bin .mtl), "" = untextured
};
